package com.atlasiq.twin;
import com.atlasiq.persistence.*;import com.atlasiq.qir.*;import jakarta.enterprise.context.ApplicationScoped;import java.util.*;
@ApplicationScoped public class ArchitectureSimulationService {private final AnalysisStore store;public ArchitectureSimulationService(AnalysisStore s){store=s;}
 public Simulation simulate(String id,Scenario r){QirModel m=store.find(id).orElseThrow(()->new NoSuchElementException("analysis not found")).model();Set<String>removed=new LinkedHashSet<>(r.removeNodeIds()==null?List.of():r.removeNodeIds());Set<String>front=new LinkedHashSet<>(removed),affected=new LinkedHashSet<>();List<QirEdge>paths=new ArrayList<>();for(int d=0;d<Math.max(1,Math.min(r.depth(),6));d++){Set<String>next=new LinkedHashSet<>();for(QirEdge e:m.edges())if(front.contains(e.to())){if(!removed.contains(e.from())&&affected.add(e.from()))next.add(e.from());paths.add(e);}front=next;}Map<String,QirNode>by=new HashMap<>();m.nodes().forEach(n->by.put(n.id(),n));List<QirNode>nodes=affected.stream().map(by::get).filter(Objects::nonNull).toList();Map<String,Long>types=nodes.stream().collect(java.util.stream.Collectors.groupingBy(QirNode::type,java.util.stream.Collectors.counting()));int risk=Math.min(100,removed.size()*15+affected.size()*6+paths.size()*2);return new Simulation(id,r,removed.size(),nodes,paths,types,risk,risk>=70?"HIGH":risk>=35?"MEDIUM":"LOW");}
 public record Scenario(List<String>removeNodeIds,int depth,String description){}public record Simulation(String analysisId,Scenario scenario,int removedComponents,List<QirNode>affectedComponents,List<QirEdge>evidencePaths,Map<String,Long>affectedByType,int riskScore,String riskLevel){}
}